window.docContents[121].resolve({"/rules/PL1005/#PL1005-limitations":{"contents":"The label is computed from the exact transitive set; a proof that merely could avoid an axiom still carries it until rewritten.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1005: Transitive axioms must fit the selected profile","header":"Limitations and unsupported cases","id":"/rules/PL1005/#PL1005-limitations"},"/rules/PL2004/#PL2004-limitations":{"contents":"Whole-project scope only: the editor is explicitly partial and does not report this rule.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2004: Owned coverage must match the exact Lake inventory","header":"Limitations and unsupported cases","id":"/rules/PL2004/#PL2004-limitations"},"/rules/PL4002/#PL4002-limitations":{"contents":"Examples are checked under the declared toolchain only.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4002: Positive examples require warning-free elaboration and admission","header":"Limitations and unsupported cases","id":"/rules/PL4002/#PL4002-limitations"},"/rules/PL5001/#PL5001-limitations":{"contents":"The editor reports this rule only when the module has finished elaborating.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL5001: Claimed modules require module documentation","header":"Limitations and unsupported cases","id":"/rules/PL5001/#PL5001-limitations"}});